import React, { useState, useEffect } from 'react';
import CarouselButton from './carouselButton/carouselButton';
import './index.scss';

const Slideshow = (props) => {
    const { arrows, items: initialItems, shape, showMarkers } = props;

    const [items, setItems] = useState(initialItems);
    const [isTransitioning, setIsTransitioning] = useState(false);
    const [displayIndex, setDisplayIndex] = useState(0); // For markers only
    
    const visibleCount = 2;
    const itemWidth = 100 / visibleCount;

    const handleNext = () => {
        if (isTransitioning) return;
        setIsTransitioning(true);
        
        // Update marker index
        setDisplayIndex((prev) => (prev + 1) % initialItems.length);
    };

    const handlePrev = () => {
        if (isTransitioning) return;
        
        // For sliding left, we move the last item to the front FIRST,
        // then animate into place.
        const newItems = [...items];
        const lastItem = newItems.pop();
        newItems.unshift(lastItem);
        
        setItems(newItems);
        setIsTransitioning(false); 
        
        // Update marker
        setDisplayIndex((prev) => (prev - 1 + initialItems.length) % initialItems.length);
    };

    const handleTransitionEnd = () => {
        if (isTransitioning) {
            setIsTransitioning(false);
            
            // Move the first item to the end of the array
            const newItems = [...items];
            const firstItem = newItems.shift();
            newItems.push(firstItem);
            
            setItems(newItems);
        }
    };

    return (
        <div className='slideshow'>
            <div className='slideshow_container'>
                {arrows && <CarouselButton onSlide={handlePrev} direction={'left'} />}
                
                <div className="slideshow_view_window">
                    <div 
                        className="slideshow_track"
                        onTransitionEnd={handleTransitionEnd}
                        style={{
                            display: 'flex',
                            transition: isTransitioning ? 'transform 0.5s ease-in-out' : 'none',
                            transform: isTransitioning 
                                ? `translateX(-${itemWidth}%)` 
                                : `translateX(0)`
                        }}
                    >
                        {/* Render extra items to ensure the "window" is always full during transition */}
                        {[...items, ...items.slice(0, visibleCount)].map((item, index) => (
                            <div
                                key={`${item.key}-${index}`}
                                className='slideshow_slide_container'
                                style={{
                                    flex: `0 0 ${itemWidth}%`,
                                    borderRadius: `${shape === 'circle' ? '100%' : '10px'}`
                                }}
                            >
                                <div className="slideshow_slide">
                                    {item}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {arrows && <CarouselButton onSlide={handleNext} direction={'right'} />}
            </div>

            {showMarkers && (
                <div className='slideshow_indices_container'>
                    {initialItems.map((_, index) => (
                        <div
                            key={index}
                            className={displayIndex === index ? 'slideshow_indices slideshow_indices_active' : 'slideshow_indices'}
                        />
                    ))}
                </div>
            )}
        </div>
    );
};

export default Slideshow;