import React, { useState, useEffect } from 'react';
import '../Home.scss';
import './Intro.scss';
import FadeIn from 'react-fade-in';
import splash_img from '../../img/splash.png';
import splash from '../../img/splash.gif';

const text = ['artist', 'designer', 'developer']

function Intro() {
    const [textVisible, setTextVisible] = useState(false);

    useEffect(() => {
        const timer = setTimeout(() => {
            setTextVisible(true);
        }, 6000);
        return () => clearTimeout(timer);
    }, []);

    return (
        <div className='sectionIntro' key={splash_img}>
            <img
                src={splash}
                key={splash}
                className='intro_img'
                alt='splash_img'
            />
            <FadeIn
                visible={true}
                delay={6000}
                transitionDuration={1000}
            >
                <div className='intro_description'>
                    <FadeIn
                        visible={textVisible}
                        delay={300}
                        transitionDuration={1000}
                    >
                        {text?.map((i) =>
                            <h className='intro_subtitle'>{i}</h>
                        )}
                    </FadeIn>
                </div>
            </FadeIn>
        </div>
    )
}

export default Intro;